query SoldListing($id: ID!) {
  externalTransaction(id: $id) {
    ...ExternalTransactionFragment
    __typename
  }
}

fragment ExternalTransactionFragment on ExternalTransaction {
  date
  id
  auctionHouse
  auctionName
  auctionType
  displayPrice
  label
  fees
  shipping
  usdAmount
  consolidatedSkippedReason
  currency
  asset {
    ...AssetBase
    __typename
  }
  attributes {
    ...ExternalTransactionAttributesFragment
    __typename
  }
  subjectToChange
  __typename
}

fragment AssetBase on Asset {
  id
  name
  year
  subject
  category
  brand
  variety
  attributes {
    cardNumber
    printRun
    __typename
  }
  __typename
}

fragment ExternalTransactionAttributesFragment on ExternalTransactionAttributes {
  grade
  gradingCompany
  cert
  url
  autograph
  imgThumbnailUrl
  images {
    position
    url
    __typename
  }
  __typename
}

query AssetMarketTransactions($id: ID!, $marketTransactionFilter: MarketTransactionFilter!) {
  asset(id: $id) {
    ...AssetMarketTransactions
    __typename
  }
}

fragment AssetMarketTransactions on Asset {
  id
  marketTransactions(marketTransactionFilter: $marketTransactionFilter) {
    ...MarketTransactionBase
    __typename
  }
  __typename
}

fragment MarketTransactionBase on MarketTransaction {
  id
  date
  auctionHouse
  auctionType
  price
  attributes {
    ...MarketTransactionAttributesBase
    __typename
  }
  subjectToChange
  consolidatedSkippedReason
  label
  __typename
}

fragment MarketTransactionAttributesBase on MarketTransactionAttributes {
  gradeNumber
  gradingCompany
  url
  autograph
  __typename
}
